#include <stdio.h>
int main() {
    char s[100]; if (scanf("%s", s) != 1) return 0;
    int mask = 0, lucky = 1;
    for (int i = 0; s[i]; i++) {
        int bit = 1 << (s[i] - '0');
        if (mask & bit) { lucky = 0; break; }
        mask |= bit;
    }
    printf("%s\n", lucky ? "YES" : "NO");
    return 0;
}

